import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"判断ガイド: 継承かコンポジションか","description":"","frontmatter":{"title":"判断ガイド: 継承かコンポジションか","study":{"source":"C++ Wiki","status":"published","summary":"根拠: 継承・委譲・コンポジション、LSP、Strategy 継承の危険シグナル: 空実装のoverride/基底のprotectedメンバを派生が直接いじる/「〜だけど〜しない」型(飛べない鳥)/派生の追加のたび基底に条件分岐が増える","section":"reference","format":"article","domain":"design"}},"headers":[],"relativePath":"design/decisions/inheritance-or-composition.md","filePath":"design/decisions/inheritance-or-composition.md"}'),i={name:"design/decisions/inheritance-or-composition.md"};function o(r,a,l,d,p,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="判断ガイド-継承かコンポジションか" tabindex="-1">判断ガイド: 継承かコンポジションか <a class="header-anchor" href="#判断ガイド-継承かコンポジションか" aria-label="Permalink to &quot;判断ガイド: 継承かコンポジションか&quot;">​</a></h1><h2 id="判断フロー" tabindex="-1">判断フロー <a class="header-anchor" href="#判断フロー" aria-label="Permalink to &quot;判断フロー&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1. 目的は「抽象(インターフェース)の実装」か?</span></span>
<span class="line"><span>    → はい ──&gt; 継承でよい(純粋仮想の実装は健全な継承)</span></span>
<span class="line"><span>Q2. 目的は「実装(コード)の再利用」か?</span></span>
<span class="line"><span>    → はい ──&gt; コンポジション(部品として持つ)を既定とする。Q3で例外確認</span></span>
<span class="line"><span>Q3. 例外チェック: 次の3条件が全部成り立つか?</span></span>
<span class="line"><span>    (a) is-aが契約レベルで成立([LSP](../02_solid/lsp.md): 置換しても呼び出し側の期待を破らない)</span></span>
<span class="line"><span>    (b) 階層は浅い(1〜2段)まま安定しそう</span></span>
<span class="line"><span>    (c) 基底の変更が派生を壊す結合を受け入れられる(同一チーム・同時変更が可能)</span></span>
<span class="line"><span>    → 全部Yes ──&gt; 継承も可(Template Method型の骨格共有など)</span></span>
<span class="line"><span>    → 1つでもNo ──&gt; コンポジション</span></span>
<span class="line"><span>Q4. 「特徴の組み合わせ」を表現したいか?(飛ぶ×撃つ×分裂)</span></span>
<span class="line"><span>    → はい ──&gt; 迷わずコンポジション(継承ツリーは組み合わせで爆発する)</span></span></code></pre></div><p>根拠: <a href="/study/design/foundations/inheritance-delegation-composition.html">継承・委譲・コンポジション</a>、<a href="/study/design/solid/lsp.html">LSP</a>、<a href="/study/design/patterns/strategy.html">Strategy</a></p><h2 id="判断材料" tabindex="-1">判断材料 <a class="header-anchor" href="#判断材料" aria-label="Permalink to &quot;判断材料&quot;">​</a></h2><ul><li><strong>継承の危険シグナル</strong>: 空実装のoverride/基底のprotectedメンバを派生が直接いじる/「〜だけど〜しない」型(飛べない鳥)/派生の追加のたび基底に条件分岐が増える</li><li><strong>コンポジションの危険シグナル</strong>: 部品が2つで固定なのに差し替え基盤を整備/部品間の通信コードが本体より太い(部品の切り方=責務の切り方が誤り)</li></ul><h2 id="例外" tabindex="-1">例外 <a class="header-anchor" href="#例外" aria-label="Permalink to &quot;例外&quot;">​</a></h2><ul><li><strong>フレームワーク規約</strong>: MonoBehaviour、AActor、Screen基底などエンジン・基盤の指定する継承は従う(規約への準拠であり、この判断の対象外)</li><li><strong>バリエーション2つで固定</strong>: enum+ifの方が誠実なこともある(継承もコンポジションも過剰)</li></ul><h2 id="トレードオフ" tabindex="-1">トレードオフ <a class="header-anchor" href="#トレードオフ" aria-label="Permalink to &quot;トレードオフ&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>継承</th><th>コンポジション</th></tr></thead><tbody><tr><td>得</td><td>記述が短い、型で能力が分かる、フックの規約提供</td><td>組み合わせ自由、実行時差し替え、弱い結合</td></tr><tr><td>失</td><td>最強の結合(基底変更の波及)、組み合わせ爆発、実行時変更不可</td><td>部品接続コード、追跡の手間、設計力を要求</td></tr></tbody></table><h2 id="実践のコツ" tabindex="-1">実践のコツ <a class="header-anchor" href="#実践のコツ" aria-label="Permalink to &quot;実践のコツ&quot;">​</a></h2><ul><li>迷ったらコンポジション(戻しやすいのはこちら。継承を剥がすのは大工事)</li><li>「継承で共有したい実装」は、大抵<strong>部品クラス1つ+両者がそれを持つ</strong>で書き直せる——書き直してみて不自然なら継承の兆候</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「インターフェースの実装」の継承が例外的に安全なのはなぜですか。</li><li>Q3の3条件のうち、実務で最も破られやすいのはどれだと思いますか。</li><li>継承もコンポジションも過剰な状況とは?</li></ol><hr><p>関連項目：<a href="/study/design/decisions/create-interface.html">インターフェースを作るべきか</a> / <a href="/study/design/decisions/">学習ガイド</a> / <a href="/study/design/decisions/abstraction-and-patterns.html">抽象化すべきか・パターンを使うべきか</a></p>`,16)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
